it('Should set cookie headers when re-assigning Response to `c.res`', () => {
  const cookies = ['foo=bar; Path=/', 'foo2=bar2; Path=/']
  const res = new Response(null)
  res.headers.append('set-cookie', cookies[0])
  res.headers.append('set-cookie', cookies[1])
  c.res = res
  expect(c.res.headers.getSetCookie().length).toBe(2)

  // Re-assign
  const newCookies = ['foo3=bar3; Path=/']
  const newResponse = new Response(null)
  newResponse.headers.append('set-cookie', newCookies[0])
  c.res = newResponse
  expect(c.res.headers.getSetCookie().length).toBe(cookies.length + newCookies.length)
  expect(c.res.headers.getSetCookie()).toEqual([...cookies, ...newCookies])
})

it('Should keep both middleware and handler cookies when the handler returns a new Response', () => {
  // Simulate middleware setting a cookie on `c.res` before the handler runs.
  c.res.headers.append('set-cookie', 'middleware=1; Path=/')

  // Simulate the handler returning a Response with its own `Set-Cookie` header.
  const handlerResponse = new Response('ok', {
    headers: { 'set-cookie': 'handler=1; Path=/' },
  })
  c.res = handlerResponse

  expect(c.res.headers.getSetCookie()).toEqual([
    'middleware=1; Path=/',
    'handler=1; Path=/',
  ])
})

